module TopModule (
    input  logic       clk,
    input  logic       reset,
    output logic [4:0] q
);

always_ff @(posedge clk) begin
    if (reset) begin
        q <= 5'd1;
    end else begin
        q[4] <= q[0];
        q[3] <= q[4];
        q[2] <= q[3] ^ q[0];
        q[1] <= q[2];
        q[0] <= q[1];
    end
end

endmodule

