module tb_TopModule;
    logic       clk;
    logic       reset;
    logic [4:0] q;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        #12;
        reset = 0;

        // Run for more than 31 cycles to check sequence and repetition
        for (int i = 0; i < 40; i++) begin
            @(posedge clk);
            $display("Time %0t: q = %0d (0x%0h)", $time, q, q);
        end

        // Check reset during operation
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: Reset did not set q to 1, got %0d", q);
            $finish;
        end
        reset = 0;
        @(posedge clk);
        if (q !== 5'd20) begin // 1 -> 20
            $display("SELFTEST FAIL: Expected 20 after reset state 1, got %0d", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic       clk;
    logic       reset;
    logic [4:0] q;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;
        #12;

        // Check reset state
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: Initial reset did not set q to 1, got %0d", q);
            $finish;
        end

        @(posedge clk);
        reset = 0;

        // Check sequence for 31 cycles
        // State 1 -> 20
        @(posedge clk);
        #1;
        if (q !== 5'd20) begin
            $display("SELFTEST FAIL: Expected 20, got %0d", q);
            $finish;
        end

        // Let it run through full period (31 cycles total) and verify it repeats 1
        for (int i = 0; i < 30; i++) begin
            @(posedge clk);
        end
        #1;
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: LFSR did not repeat after 31 cycles, got %0d", q);
            $finish;
        end

        // Test asynchronous/synchronous reset during operation
        @(posedge clk);
        reset = 1;
        @(posedge clk);
        #1;
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: Synchronous reset during operation failed, got %0d", q);
            $finish;
        end

        reset = 0;
        @(posedge clk);
        #1;
        if (q !== 5'd20) begin
            $display("SELFTEST FAIL: Expected 20 after releasing reset, got %0d", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule

module tb_TopModule;
    logic       clk;
    logic       reset;
    logic [4:0] q;

    TopModule uut (
        .clk(clk),
        .reset(reset),
        .q(q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        reset = 1;

        // Wait for a couple of clock cycles with reset high
        @(posedge clk);
        @(posedge clk);

        // Check reset state
        #1;
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: Initial reset did not set q to 1, got %0d", q);
            $finish;
        end

        // Release reset
        reset = 0;

        // At next posedge, q should update from 1 to 20
        @(posedge clk);
        #1;
        if (q !== 5'd20) begin
            $display("SELFTEST FAIL: Expected 20, got %0d", q);
            $finish;
        end

        // Let it run through remaining 30 cycles (31 total period) and verify it returns to 1
        repeat (30) begin
            @(posedge clk);
        end
        #1;
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: LFSR did not repeat after 31 cycles, got %0d", q);
            $finish;
        end

        // Test synchronous reset during operation
        @(posedge clk);
        reset = 1;
        #1;
        // On posedge, reset is sampled high, but q updates on posedge.
        // Wait for posedge clk to capture reset
        @(posedge clk);
        #1;
        if (q !== 5'd1) begin
            $display("SELFTEST FAIL: Synchronous reset during operation failed, got %0d", q);
            $finish;
        end

        reset = 0;
        @(posedge clk);
        #1;
        if (q !== 5'd20) begin
            $display("SELFTEST FAIL: Expected 20 after releasing reset, got %0d", q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
